import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def token():
    global tok
    while True:
        try:
            tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST")))["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    global tok
    if not tok: token()
    for i in range(200):
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})))
        except urllib.error.HTTPError as e:
            if e.code==404: return None
            if e.code==401: token();continue
            if e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1));continue
            notes.append((p,e.code));time.sleep(0.5)
        except Exception as e: notes.append((p,str(e)));time.sleep(0.5)
    raise SystemExit("fail "+p)
seen=set();dups=0;orders=[];p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen: dups+=1;continue
        seen.add(o["id"]);orders.append(o)
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
statuses=set()
for o in orders:
    statuses.add(o["status"])
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: odd.append(("naive",o["placed_at"]));t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c));continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2)
print(r,pages,len(orders),statuses,odd[:20],len(odd),notes[:10],len(notes))
EOF
